"use client";

import React, { useCallback, useEffect, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Paper,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import { Add, Save } from "@mui/icons-material";
import { BRAND } from "@/libs/theme_palette";
import {
  Actions,
  EmptyRow,
  Field,
  FormGrid,
  PageHeading,
  TODAY,
  api,
  currentUser,
  fieldSx,
  headSx,
  panelSx,
  useSearch,
} from "@/app/components/quejas/shared";

const EMPTY = {
  proveedor: "",
  sap: "",
  material: "",
  fecha: TODAY,
  serial_lote: "",
  piezas_totales: "",
  piezas_ok: "",
  piezas_nok: "",
  comentario: "",
};

const COLUMNS = [
  "Acciones",
  "ID",
  "Fecha",
  "Proveedor",
  "SAP",
  "Material",
  "Serial / Lote",
  "Total",
  "OK",
  "NOK",
  "Comentario",
  "Resultado",
];

function ResultChip({ row }) {
  if (row.eliminado_en) {
    return <Chip size="small" label="ELIMINADO" />;
  }
  const aprobado = row.estatus === "APROBADO";
  return (
    <Chip
      size="small"
      label={aprobado ? "APROBADO" : "RECHAZADO"}
      color={aprobado ? "success" : "error"}
    />
  );
}

export default function SorteosCrud() {
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [editingId, setEditingId] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showDeleted, setShowDeleted] = useState(false);
  const [search, setSearch] = useState("");
  const [message, setMessage] = useState("");
  const [severity, setSeverity] = useState("success");
  const visible = useSearch(rows, search);

  const notify = useCallback((text, tone = "success") => {
    setMessage(text);
    setSeverity(tone);
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const result = await api(
        `/api/sorteos${showDeleted ? "?eliminados=1" : ""}`,
      );
      setRows(result.data);
    } catch (error) {
      notify(error.message, "error");
    } finally {
      setLoading(false);
    }
  }, [notify, showDeleted]);

  useEffect(() => {
    const timer = setTimeout(load, 0);
    return () => clearTimeout(timer);
  }, [load]);

  const reset = () => {
    setForm(EMPTY);
    setEditingId(null);
    setDialogOpen(false);
  };

  const openCreate = () => {
    setEditingId(null);
    setForm(EMPTY);
    setDialogOpen(true);
  };

  const edit = (row) => {
    setEditingId(row.id);
    setForm({
      proveedor: row.proveedor ?? "",
      sap: row.sap ?? "",
      material: row.material ?? "",
      fecha: row.fecha ?? TODAY,
      serial_lote: row.serial_lote ?? "",
      piezas_totales: row.piezas_totales ?? "",
      piezas_ok: row.piezas_ok ?? "",
      piezas_nok: row.piezas_nok ?? "",
      comentario: row.comentario ?? "",
    });
    setDialogOpen(true);
  };

  const totales = Number(form.piezas_totales) || 0;
  const suma = (Number(form.piezas_ok) || 0) + (Number(form.piezas_nok) || 0);
  const sumaValida = totales > 0 && suma === totales;
  const capturaLista =
    Boolean(form.proveedor.trim()) &&
    Boolean(form.sap.trim()) &&
    Boolean(form.material.trim()) &&
    Boolean(form.fecha);

  const save = async () => {
    setSaving(true);
    try {
      await api("/api/sorteos", {
        method: editingId ? "PUT" : "POST",
        body: JSON.stringify({
          ...form,
          id: editingId,
          usuario: currentUser(),
        }),
      });
      notify(editingId ? "Sorteo actualizado" : "Sorteo guardado");
      reset();
      await load();
    } catch (error) {
      notify(error.message, "error");
    } finally {
      setSaving(false);
    }
  };

  const changeDeleted = async (row, method) => {
    if (
      method === "DELETE" &&
      !window.confirm(`¿Eliminar el sorteo #${row.id}?`)
    ) {
      return;
    }
    try {
      await api("/api/sorteos", {
        method,
        body: JSON.stringify({ id: row.id, usuario: currentUser() }),
      });
      notify(method === "PATCH" ? "Sorteo restaurado" : "Sorteo eliminado");
      await load();
    } catch (error) {
      notify(error.message, "error");
    }
  };

  return (
    <>
      <Paper elevation={0} sx={panelSx}>
        <PageHeading
          title="Sorteos especiales"
          description="Registra el resultado de cada sorteo: piezas OK, NOK y el estatus derivado."
          search={search}
          setSearch={setSearch}
          showDeleted={showDeleted}
          setShowDeleted={setShowDeleted}
        >
          <Button variant="contained" startIcon={<Add />} onClick={openCreate}>
            Nuevo sorteo
          </Button>
        </PageHeading>
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow sx={{ bgcolor: BRAND.navy }}>
                {COLUMNS.map((heading) => (
                  <TableCell key={heading} sx={headSx} align="center">
                    {heading}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {!visible.length ? (
                <EmptyRow columns={COLUMNS.length} loading={loading} />
              ) : (
                visible.map((row) => (
                  <TableRow
                    key={row.id}
                    hover
                    sx={{ opacity: row.eliminado_en ? 0.55 : 1 }}
                  >
                    <TableCell align="center">
                      <Actions
                        row={row}
                        onEdit={edit}
                        onDelete={(item) => changeDeleted(item, "DELETE")}
                        onRestore={(item) => changeDeleted(item, "PATCH")}
                      />
                    </TableCell>
                    <TableCell align="center">{row.id}</TableCell>
                    <TableCell align="center">{row.fecha}</TableCell>
                    <TableCell>{row.proveedor}</TableCell>
                    <TableCell>{row.sap}</TableCell>
                    <TableCell>{row.material}</TableCell>
                    <TableCell align="center">
                      {row.serial_lote || "—"}
                    </TableCell>
                    <TableCell align="center">{row.piezas_totales}</TableCell>
                    <TableCell align="center">{row.piezas_ok}</TableCell>
                    <TableCell align="center">{row.piezas_nok}</TableCell>
                    <TableCell>{row.comentario || "—"}</TableCell>
                    <TableCell align="center">
                      <ResultChip row={row} />
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      <Dialog
        open={dialogOpen}
        onClose={() => !saving && reset()}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>
          {editingId ? `Editar sorteo #${editingId}` : "Nuevo sorteo especial"}
        </DialogTitle>
        <DialogContent dividers>
          <FormGrid>
            <Field
              name="proveedor"
              label="Proveedor"
              form={form}
              setForm={setForm}
              required
              upper
              autoFocus
            />
            <Field
              name="sap"
              label="Número SAP"
              form={form}
              setForm={setForm}
              required
              upper
            />
            <Field
              name="material"
              label="Material"
              form={form}
              setForm={setForm}
              required
              upper
            />
            <Field
              name="fecha"
              label="Fecha"
              type="date"
              form={form}
              setForm={setForm}
              required
            />
            <Field
              name="serial_lote"
              label="Serial / Lote"
              form={form}
              setForm={setForm}
              upper
            />
            <Field
              name="piezas_totales"
              label="Piezas totales"
              type="number"
              form={form}
              setForm={setForm}
              required
            />
            <Field
              name="piezas_ok"
              label="Piezas OK"
              type="number"
              form={form}
              setForm={setForm}
              required
            />
            <Field
              name="piezas_nok"
              label="Piezas NOK"
              type="number"
              form={form}
              setForm={setForm}
              required
            />
            <Box sx={{ gridColumn: { sm: "span 2", lg: "span 3" } }}>
              <Field
                name="comentario"
                label="Comentario"
                form={form}
                setForm={setForm}
                multiline
                minRows={2}
                upper
                sx={fieldSx}
              />
            </Box>
          </FormGrid>
          {!sumaValida && (
            <Alert severity="info" sx={{ mt: 2 }}>
              Las piezas OK y NOK deben sumar exactamente el total inspeccionado
              (llevas {suma} de {totales}).
            </Alert>
          )}
          {sumaValida && (
            <Alert
              severity={Number(form.piezas_nok) > 0 ? "error" : "success"}
              sx={{ mt: 2 }}
            >
              Este registro se guardará como{" "}
              <strong>
                {Number(form.piezas_nok) > 0 ? "RECHAZADO" : "APROBADO"}
              </strong>
              .
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={reset} disabled={saving}>
            Cancelar
          </Button>
          <Button
            variant="contained"
            startIcon={<Save />}
            onClick={save}
            disabled={saving || !sumaValida || !capturaLista}
          >
            {saving ? "Guardando..." : "Guardar"}
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={Boolean(message)}
        autoHideDuration={4500}
        onClose={() => setMessage("")}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          severity={severity}
          variant="filled"
          onClose={() => setMessage("")}
          sx={{ width: "100%" }}
        >
          {message}
        </Alert>
      </Snackbar>
    </>
  );
}
